import "server-only";
import { readFileSync } from "node:fs";
import path from "node:path";

export type Section = { id: string; heading: string; text: string };

let cache: Record<string, Section[]> | null = null;

/** Lesson text generated by scripts/gen-lesson-text.mjs, keyed "<course>/<slug>". */
function allLessons(): Record<string, Section[]> {
  cache ??= JSON.parse(readFileSync(path.join(process.cwd(), "src/content/generated/lesson-text.json"), "utf8"));
  return cache!;
}

export function lessonSectionsFor(courseId: string, slug: string): Section[] {
  return allLessons()[`${courseId}/${slug}`] ?? [];
}

function render(sections: Section[]): string {
  return sections.map((s) => (s.heading ? `## ${s.heading}\n\n${s.text}` : s.text)).join("\n\n");
}

/**
 * The lesson as markdown, trimmed to `maxChars` by dropping whole sections from the end.
 * When trimmed, the remaining headings are still listed so the model knows they exist.
 */
export function lessonText(courseId: string, slug: string, maxChars = 24_000): string {
  const sections = lessonSectionsFor(courseId, slug);
  const kept: Section[] = [];
  let size = 0;
  for (const s of sections) {
    size += s.heading.length + s.text.length + 6;
    if (size > maxChars && kept.length > 0) break;
    kept.push(s);
  }
  const dropped = sections.slice(kept.length);
  const note = dropped.length ? `\n\n(Later sections, not shown: ${dropped.map((s) => s.heading).join("; ")})` : "";
  return render(kept) + note;
}

/** One section by heading id, plus its subsections (up to the next heading of the same level). */
export function sectionText(courseId: string, slug: string, anchor: string, maxChars = 6_000): string {
  const sections = lessonSectionsFor(courseId, slug);
  const start = sections.findIndex((s) => s.id === anchor);
  if (start === -1) return lessonText(courseId, slug, maxChars);
  const picked = [sections[start]];
  for (const s of sections.slice(start + 1)) {
    if (render(picked).length > maxChars) break;
    picked.push(s);
    if (picked.length >= 4) break;
  }
  return render(picked).slice(0, maxChars);
}
